    impl PermissionPolicy<()> for ReplacePolicy {
        async fn check(
            &self,
            _: &RunContext<()>,
            _: &str,
            _: &serde_json::Value,
        ) -> PermissionDecision {
            PermissionDecision::Replace {
                args: self.0.clone(),
            }
        }
    }

    struct DenyPolicy;
    #[async_trait]
    impl PermissionPolicy<()> for DenyPolicy {
        async fn check(
            &self,
            _: &RunContext<()>,
            _: &str,
            _: &serde_json::Value,
        ) -> PermissionDecision {
            PermissionDecision::Deny {
                reason: "policy says no".into(),
            }
        }
    }

